insert into public.clients (id, business_name, initials, contact_name, email, phone, niche, region, country, timezone, package_name, monthly_fee, lead_target_min, lead_target_max, started_on, billing_day, show_cost_per_lead, show_ad_spend, active) values ('11111111-1111-4111-a111-111111111111', 'Mike''s Plumbing', 'MP', 'Mike', 'demo@leadhivenz.com', '021 555 0192', 'Emergency plumber', 'Auckland', 'NZ', 'Pacific/Auckland', 'Starter', '1500', '15', '25', '2026-06-01', '1', 'true', 'false', 'true');
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('c736fdf1-d55f-41e4-a503-5429a3160c2d', '11111111-1111-4111-a111-111111111111', '2026-06', 'published', 'First month in and we''re already inside the target range. The campaign is still learning, so expect leads to climb from here as Google works out which searches turn into calls for you.', '[{"title":"Keyword refinement","body":"Adding negative keywords for DIY and price-shopping searches so the budget only goes to people who need a plumber now."},{"title":"Ad copy testing","body":"Running two headline variants to see whether ''same day'' or ''24/7'' pulls more calls."},{"title":"Call hours","body":"Tightening the ad schedule to the hours you answer best."}]'::jsonb, '2026-07-02T06:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('c736fdf1-d55f-41e4-a503-5429a3160c2d', 612);
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('3661f275-600d-4b2d-aaf7-e73603685e11', '11111111-1111-4111-a111-111111111111', '2026-07', 'published', 'Up on June, with more calls landing in the afternoon. Missed calls crept up a little; the ones you did answer were strong, mostly blocked drains and hot water.', '[{"title":"Missed call follow-up","body":"4 of 19 calls went unanswered. Each one is a job that probably went to the next plumber on Google. Even a text back within 10 minutes recovers a lot of these."},{"title":"Scaling what''s working","body":"''Blocked drain'' searches are converting best, so I''m moving more of the budget there."},{"title":"Keyword refinement","body":"Weekly search term review, more negatives added."}]'::jsonb, '2026-08-02T06:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('3661f275-600d-4b2d-aaf7-e73603685e11', 688);
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('04909c94-cb19-4820-a9ed-4bc103c480df', '11111111-1111-4111-a111-111111111111', '2026-08', 'published', 'Best month yet: 27 leads against a 15 to 25 plan. Hot water cylinder searches picked up with the cold snap and the ads were there for it.', '[{"title":"Scaling what''s working","body":"We cleared the top of the target range, so I''m pushing bids on the hot water and burst pipe terms to hold this volume."},{"title":"Keyword refinement","body":"Added 14 negatives after the search term review. ''Plumbing course'' and ''plumber salary'' were burning clicks."},{"title":"Landing page","body":"Added a hot water cylinder page so those searches land on a page about hot water, not the generic one."}]'::jsonb, '2026-09-02T06:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('04909c94-cb19-4820-a9ed-4bc103c480df', 741);
insert into public.months (id, client_id, ym, status, summary, points, published_at) values ('e08103f3-dda9-4ce7-ab3f-8d746b218f9a', '11111111-1111-4111-a111-111111111111', '2026-09', 'published', 'A steady month. 22 leads, inside the plan. The one thing to work on is answering: 4 calls went to voicemail or rang out, all between 12 and 2pm. The jobs you tagged as won this month came to $5,750, from a $1,500 plan.', '[{"title":"Missed call follow-up","body":"22% of calls weren''t answered. I''ve shifted the ad schedule so fewer calls land over lunch, but a quick call-back on the missed ones is the easiest money in this report."},{"title":"Scaling what''s working","body":"''Emergency plumber Auckland'' and ''blocked drain'' are still the winners. More budget there, less on the broad ''plumber near me'' term."},{"title":"Keyword refinement","body":"Search term review done weekly. 9 new negatives this month."}]'::jsonb, '2026-10-02T05:00:00.000Z');
insert into public.month_private (month_id, ad_spend) values ('e08103f3-dda9-4ce7-ab3f-8d746b218f9a', 702);
